"use client";
import { useState } from 'react';
import { parseEther } from 'viem';
import { getWalletClient } from '@/lib/client';
import { VenturePost } from '@/lib/feed';

const SPLITTER_ABI = [{
  name: 'supportCreator',
  type: 'function',
  stateMutability: 'payable',
  inputs: [{ name: '_creator', type: 'address' }],
  outputs: [],
}] as const;

export default function VentureCard({ post, userAccount }: { post: VenturePost, userAccount: string }) {
  const [loading, setLoading] = useState(false);

  const support = async () => {
    setLoading(true);
    try {
      const client = await getWalletClient();
      if (!client) return;

      const hash = await client.writeContract({
        address: process.env.NEXT_PUBLIC_SPLITTER_ADDR as `0x${string}`,
        abi: SPLITTER_ABI,
        functionName: 'supportCreator',
        args: [post.creatorAddress],
        value: parseEther('10'), // Fixed 10 XDC support for now
        account: userAccount as `0x${string}`,
      });

      alert(`Success! 9.5 XDC sent to @${post.username}, 0.5 XDC to Treasury. TX: ${hash}`);
    } catch (e) {
      console.error(e);
      alert("Transaction failed. Check your XDC balance.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-zinc-900 rounded-[2.5rem] overflow-hidden border border-zinc-800 mb-6 shadow-2xl">
      <img src={post.image} alt="Post" className="w-full h-72 object-cover" />
      <div className="p-8">
        <div className="flex justify-between items-center mb-4">
          <span className="text-blue-500 font-black text-sm uppercase tracking-widest">@{post.username}</span>
          <span className="bg-zinc-800 px-3 py-1 rounded-full text-[10px] font-bold text-zinc-400">GOAL: {post.fundingGoal}</span>
        </div>
        <p className="text-white text-lg font-medium leading-relaxed mb-8">{post.content}</p>
        
        <button 
          onClick={support}
          disabled={loading}
          className="w-full bg-white text-black py-4 rounded-2xl font-black hover:bg-zinc-200 transition-all active:scale-95 flex items-center justify-center gap-2"
        >
          {loading ? "Processing..." : `Invest 10 XDC`}
        </button>
      </div>
    </div>
  );
}