"use client";
import { useState, useEffect, useCallback } from 'react';
import { publicClient, getWalletClient } from '@/lib/client';
import ClaimHandle from '@/components/ClaimHandle';
import ProfileHeader from '@/components/ProfileHeader';
import VentureCard from '@/components/VentureCard';
import { MOCK_FEED } from '@/lib/feed';

export default function Home() {
  const [account, setAccount] = useState<string | null>(null);
  const [hasHandle, setHasHandle] = useState<boolean>(false);
  const [loading, setLoading] = useState(true);

  // Checks the Registry contract to see if the user exists
  const checkHandle = useCallback(async (address: string) => {
    try {
      const profile = await publicClient.readContract({
        address: process.env.NEXT_PUBLIC_REGISTRY_ADDR as `0x${string}`,
        abi: [{
          name: 'getProfile',
          type: 'function',
          stateMutability: 'view',
          inputs: [{ name: '_user', type: 'address' }],
          outputs: [{ name: 'username', type: 'string' }, { name: 'metadataCID', type: 'string' }],
        }],
        functionName: 'getProfile',
        args: [address as `0x${string}`],
      });
      
      // If index 0 (username) has a value, they are registered
      setHasHandle(!!profile[0]);
    } catch (e) {
      setHasHandle(false);
    }
  }, []);

  // On mount: Auto-detect XDCPay session and check Registry
  useEffect(() => {
    const init = async () => {
      const client = await getWalletClient();
      if (client) {
        const addresses = await client.getAddresses();
        if (addresses.length > 0) {
          setAccount(addresses[0]);
          await checkHandle(addresses[0]);
        }
      }
      setLoading(false);
    };
    init();
  }, [checkHandle]);

  const connect = async () => {
    const client = await getWalletClient();
    if (client) {
      const [address] = await client.requestAddresses();
      setAccount(address);
      await checkHandle(address);
    }
  };

  if (loading) return (
    <div className="min-h-screen bg-black flex items-center justify-center">
      <p className="text-zinc-500 font-bold animate-pulse tracking-widest">INITIALIZING PROTOCOL...</p>
    </div>
  );

  return (
    <main className="min-h-screen bg-black text-white p-6">
      <div className="max-w-xl mx-auto">
        
        {/* Branding & Wallet Toggle */}
        <header className="flex justify-between items-center mb-12">
          <div>
            <h1 className="text-3xl font-black italic tracking-tighter text-white">HARD FORK</h1>
            <p className="text-[10px] text-blue-500 font-bold tracking-[0.3em] uppercase">Balson Enterprises</p>
          </div>
          <button 
            onClick={connect} 
            className="bg-zinc-900 hover:bg-zinc-800 px-6 py-2.5 rounded-full text-xs font-bold border border-zinc-800 transition-all shadow-lg"
          >
            {account ? `${account.slice(0,6)}...${account.slice(-4)}` : "Connect Wallet"}
          </button>
        </header>

        {/* Auth State Manager */}
        {!account ? (
          <section className="text-center py-24 bg-zinc-900/40 rounded-[3rem] border border-zinc-800 border-dashed">
            <h2 className="text-2xl font-bold mb-3">Venture Capital, Socialized.</h2>
            <p className="text-zinc-500 mb-8 max-w-xs mx-auto text-sm leading-relaxed">
              Connect XDCPay to claim your handle and support the next generation of infrastructure.
            </p>
            <button 
              onClick={connect} 
              className="bg-white text-black px-12 py-4 rounded-2xl font-black hover:scale-105 transition-transform active:scale-95 shadow-xl shadow-white/5"
            >
              Enter App
            </button>
          </section>
        ) : (
          <div className="space-y-10">
            {/* Identity Logic */}
            <section>
              {hasHandle ? (
                <ProfileHeader account={account} />
              ) : (
                <ClaimHandle 
                  account={account} 
                  onSuccess={() => checkHandle(account)} 
                />
              )}
            </section>

            {/* THE VENTURE FEED */}
            <section className="pt-4">
               <div className="flex items-center gap-4 mb-8">
                 <p className="text-zinc-600 font-black uppercase text-[10px] tracking-[0.25em]">Live Ventures</p>
                 <div className="h-[1px] flex-1 bg-zinc-900" />
               </div>
               
               <div className="space-y-6">
                 {MOCK_FEED.map((post) => (
                   <VentureCard 
                    key={post.id} 
                    post={post} 
                    userAccount={account} 
                   />
                 ))}
               </div>

               {/* Empty State / Footer */}
               <div className="py-20 text-center border-t border-zinc-900 mt-12">
                 <p className="text-zinc-700 text-sm italic">You've reached the end of the fork.</p>
               </div>
            </section>
          </div>
        )}
      </div>
    </main>
  );
}